{"path":"services.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Offerings — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fbfbf8;--muted:#6b6b63;--accent:#6a9f86;--card:#fff;--ink:#222}
    html,body{height:100%;margin:0;font-family:Inter, system-ui, -apple-system, "Segoe UI", Roboto, "Helvetica Neue", Arial; color:var(--ink);background:var(--bg);}
    header{display:flex;align-items:center;justify-content:space-between;padding:18px 28px;border-bottom:1px solid rgba(0,0,0,.04);position:sticky;top:0;background:linear-gradient(180deg,rgba(255,255,255,0.8),rgba(255,255,255,0.6));backdrop-filter:blur(6px);z-index:20}
    .brand{display:flex;gap:12px;align-items:center}
    .brand svg{width:44px;height:44px}
    nav a{margin-left:18px;color:var(--muted);text-decoration:none;font-weight:600;font-size:14px}
    .hero{padding:56px 28px;display:grid;grid-template-columns:1fr 420px;gap:28px;align-items:start;background-image:url('assets/img/pattern.svg');background-repeat:repeat;}
    .lead{max-width:64ch}
    h1{margin:0 0 8px 0;font-size:28px;letter-spacing:-0.02em}
    p.lede{margin:0;color:var(--muted);line-height:1.5}
    .aside-card{background:var(--card);padding:20px;border-radius:12px;box-shadow:0 6px 20px rgba(38,64,54,0.06)}
    .grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:18px;margin:28px 0}
    .service{background:linear-gradient(180deg,rgba(255,255,255,1),#fbfbfb);padding:18px;border-radius:10px;border:1px solid rgba(0,0,0,0.04)}
    .service h3{margin:0 0 8px 0;font-size:16px}
    .muted{color:var(--muted);font-size:14px}
    .cta{display:inline-block;padding:10px 14px;background:var(--accent);color:white;border-radius:8px;text-decoration:none;font-weight:700;margin-top:12px}
    footer.section-cta{padding:42px 28px;text-align:center}
    .reveal{opacity:0;transform:translateY(14px);transition:opacity .6s cubic-bezier(.2,.9,.3,1),transform .6s cubic-bezier(.2,.9,.3,1)}
    .reveal.is-revealed{opacity:1;transform:none}
    /* Session Planner */
    .planner{margin-top:12px}
    .planner label{display:block;font-size:13px;margin-top:10px}
    .planner input,.planner textarea,.planner select{width:100%;padding:10px;border-radius:8px;border:1px solid rgba(0,0,0,0.07);margin-top:6px;font-size:14px}
    .planner .controls{display:flex;gap:8px;margin-top:12px}
    .btn{padding:10px 12px;border-radius:8px;border:none;background:#2f6e5f;color:#fff;font-weight:700;cursor:pointer}
    .btn.secondary{background:#e6ebe6;color:var(--ink)}
    .summary{white-space:pre-wrap;margin-top:12px;padding:12px;background:#fff;border-radius:8px;border:1px dashed rgba(0,0,0,0.06);font-family:monospace;font-size:13px}
    @media(max-width:860px){.hero{grid-template-columns:1fr;}.aside-card{order:2}}
  </style>
</head>
<body>
  <header>
    <div class="brand">
      <svg viewBox="0 0 64 64" xmlns="http://www.w3.org/2000/svg" aria-hidden><rect width="64" height="64" rx="12" fill="#e8f6f0"/><circle cx="32" cy="28" r="10" fill="#a6d8c4"/><path d="M18 46c6-8 22-8 28 0" stroke="#6a9f86" stroke-width="3" fill="none" stroke-linecap="round"/></svg>
      <div>
        <div style="font-weight:800">{{BUSINESS_NAME}}</div>
        <div style="font-size:12px;color:var(--muted)">A practical path to steadier days</div>
      </div>
    </div>
    <nav>
      <a href="index.html">Hearth</a>
      <a href="services.html" aria-current="page">Offerings</a>
      <a href="conditions.html">Concerns</a>
      <a href="approach.html">Way</a>
      <a href="pricing.html">Plans</a>
      <a href="about.html">Seed</a>
      <a href="book.html">Reserve</a>
      <a href="contact.html">Connect</a>
    </nav>
  </header>

  <main>
    <section class="hero">
      <div class="lead">
        <h1 class="reveal" data-delay="0">Pragmatic, whole-person consultations</h1>
        <p class="lede reveal" data-delay="80">Small, clear steps built into your week — tools you can actually use. Sessions blend conversation, gentle guidance, and targeted plans that respect real life.</p>

        <div class="reveal" data-delay="160">
          <div class="grid">
            <div class="service">
              <h3>CycleCare Session</h3>
              <div class="muted">For recurring patterns — 50–60 min</div>
              <div style="margin-top:8px;font-weight:700">Suggested investment: $165</div>
              <div style="margin-top:10px" class="muted">A focused visit to map rhythms and small shifts you can try.</div>
            </div>
            <div class="service">
              <h3>Foundations Visit</h3>
              <div class="muted">Intro + roadmap — 75 min</div>
              <div style="margin-top:8px;font-weight:700">Suggested investment: $225</div>
              <div style="margin-top:10px" class="muted">A deeper look and a practical plan for the coming months.</div>
            </div>
            <div class="service">
              <h3>Harmony Check</h3>
              <div class="muted">Follow-up — 30 min</div>
              <div style="margin-top:8px;font-weight:700">Suggested investment: $95</div>
              <div style="margin-top:10px" class="muted">Short tune-ups to keep momentum steady.</div>
            </div>
            <div class="service">
              <h3>Transition Series</h3>
              <div class="muted">4 visits, paced — plan & review</div>
              <div style="margin-top:8px;font-weight:700">Suggested investment: $720</div>
              <div style="margin-top:10px" class="muted">A compact course to test and refine a new routine.</div>
            </div>
          </div>
        </div>

        <div class="reveal" data-delay="240">
          <a class="cta" href="book.html">{{PRIMARY_CTA_LABEL}}</a>
        </div>
      </div>

      <aside class="aside-card reveal" data-delay="320">
        <h3 style="margin:0 0 8px 0">Session Planner</h3>
        <div style="font-size:13px;color:var(--muted)">Build a short, shareable plan to bring to your visit.</div>

        <form id="plannerServices" class="planner" onsubmit="return false;">
          <label for="concern">Primary focus</label>
          <input id="concern" name="concern" placeholder="Sleep, digestion, stress, cycle, energy..." required>

          <label for="length">Preferred session length</label>
          <select id="length" name="length">
            <option>30 min</option>
            <option>50–60 min</option>
            <option>75 min</option>
          </select>

          <label for="constraints">Lifestyle constraints</label>
          <input id="constraints" name="constraints" placeholder="Time, mobility, budget, food preferences">

          <label for="goals">Three small goals</label>
          <input id="g1" placeholder="1) " style="margin-top:6px">
          <input id="g2" placeholder="2) " style="margin-top:6px">
          <input id="g3" placeholder="3) " style="margin-top:6px">

          <div style="display:flex;gap:8px;margin-top:10px;flex-wrap:wrap">
            <label style="font-size:13px"><input type="checkbox" id="pref-nut"/> Nutrition</label>
            <label style="font-size:13px"><input type="checkbox" id="pref-move"/> Movement</label>
            <label style="font-size:13px"><input type="checkbox" id="pref-herb"/> Plant supports</label>
            <label style="font-size:13px"><input type="checkbox" id="pref-mind"/> Breath/Rest</label>
          </div>

          <div class="controls">
            <button class="btn" id="buildBtn">Draft plan</button>
            <button class="btn secondary" id="resetBtn" type="button">Clear</button>
          </div>

          <div id="summary" class="summary" aria-live="polite"></div>
          <div style="display:flex;gap:8px;margin-top:8px">
            <button class="btn" id="copyBtn" type="button">Copy summary</button>
            <a id="downloadLink" class="btn secondary" style="display:inline-block;text-decoration:none;padding:10px 12px;">Download</a>
          </div>
        </form>
      </aside>
    </section>

    <section style="padding:28px" class="reveal" data-delay="400">
      <h2 style="margin-top:0">How we frame visits</h2>
      <p class="muted">Each meeting is an invitation: quiet noticing, practical set-ups, and one measurable step you can try that week. We favor experiments that fit your days.</p>
    </section>

    <section style="padding:0 28px 32px 28px;display:flex;gap:18px;flex-wrap:wrap">
      <div style="flex:1;min-width:240px" class="reveal" data-delay="480">
        <div style="background:#fff;padding:18px;border-radius:10px;border:1px solid rgba(0,0,0,0.04)">
          <h3 style="margin:0 0 8px 0">What to expect</h3>
          <div class="muted">A respectful conversation, a realistic plan, and follow-up that keeps it simple.</div>
        </div>
      </div>
      <div style="flex:1;min-width:240px" class="reveal" data-delay="560">
        <div style="background:#fff;padding:18px;border-radius:10px;border:1px solid rgba(0,0,0,0.04)">
          <h3 style="margin:0 0 8px 0">Payment & insurance</h3>
          <div class="muted">We suggest amounts above; sessions can be paid by card. Insurance policies vary — ask us and we can provide a receipt.</div>
        </div>
      </div>
    </section>

    <footer class="section-cta">
      <a class="cta" href="book.html">Reserve a time</a>
      <div style="margin-top:10px;color:var(--muted);font-size:13px">Or call <strong>{{PHONE}}</strong></div>
    </footer>
  </main>

  <script>
    // Scroll reveal with prefers-reduced-motion support
    (function(){
      const prefersReduce = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      const reveals = Array.from(document.querySelectorAll('.reveal'));
      if(prefersReduce){ reveals.forEach(el=>el.classList.add('is-revealed')); return; }
      const io = new IntersectionObserver(entries=>{
        entries.forEach(entry=>{
          if(entry.isIntersecting){
            const el = entry.target;
            const delay = parseInt(el.getAttribute('data-delay')||0,10);
            setTimeout(()=>el.classList.add('is-revealed'), delay);
            io.unobserve(el);
          }
        });
      },{threshold:0.12});
      reveals.forEach(r=>io.observe(r));
    })();

    // Session Planner logic
    (function(){
      function el(id){return document.getElementById(id)}
      const buildBtn = el('buildBtn');
      const resetBtn = el('resetBtn');
      const copyBtn = el('copyBtn');
      const downloadLink = el('downloadLink');
      const summary = el('summary');

      function gather(){
        const concern = el('concern').value.trim();
        const length = el('length').value;
        const constraints = el('constraints').value.trim();
        const goals = [el('g1').value, el('g2').value, el('g3').value].map(s=>s.trim()).filter(Boolean);
        const prefs = [];
        if(el('pref-nut').checked) prefs.push('Nutrition');
        if(el('pref-move').checked) prefs.push('Movement');
        if(el('pref-herb').checked) prefs.push('Plant supports');
        if(el('pref-mind').checked) prefs.push('Breath/Rest');
        return {concern,length,constraints,goals,prefs};
      }

      function buildText(data){
        const lines = [];
        lines.push('Session Plan — '+(new Date()).toLocaleDateString());
        lines.push('Primary focus: '+(data.concern||'—'));
        lines.push('Session length: '+(data.length||'—'));
        if(data.constraints) lines.push('Constraints: '+data.constraints);
        if(data.prefs.length) lines.push('Preferences: '+data.prefs.join(', '));
        if(data.goals.length){ lines.push('Goals:'); data.goals.forEach((g,i)=>lines.push('  '+(i+1)+'. '+g)); }
        lines.push('Suggested first steps:');
        // small heuristic suggestions
        if(/sleep|rest|insom/i.test(data.concern)) lines.push('  • Wind-down ritual: 20–30 min of low screen time; simple breath practice before bed.');
        if(/digest|gut|bloat/i.test(data.concern)) lines.push('  • Three-day note: jot meals & symptoms to notice patterns; gentle meal spacing.');
        if(/stress|anx|mood/i.test(data.concern)) lines.push('  • Micro check-ins: two 3-minute breathing breaks daily; track feeling briefly.');
        if(data.prefs.includes('Movement')) lines.push('  • Movement: three short walks this week, 10–15 minutes each.');
        if(data.prefs.includes('Nutrition')) lines.push('  • Nutrition: one small swap per day (e.g., add a serving of veg).');
        if(!(/sleep|digest|stress|anx|mood|gut|insom/i.test(data.concern))) lines.push('  • A single measurable step to try this week: pick one and notice how it lands.');
        lines.push('Notes for visit: bring any recent labs, a short timeline, and this plan.');
        return lines.join('\n');
      }

      buildBtn.addEventListener('click',()=>{
        const data = gather();
        const text = buildText(data);
        summary.textContent = text;
        // prepare download
        const blob = new Blob([text],{type:'text/plain'});
        const url = URL.createObjectURL(blob);
        downloadLink.href = url; downloadLink.download = 'session-plan.txt';
      });

      resetBtn.addEventListener('click',()=>{
        document.getElementById('plannerServices').reset();
        summary.textContent = '';
        downloadLink.removeAttribute('href');
      });

      copyBtn.addEventListener('click',async()=>{
        const txt = summary.textContent;
        if(!txt) return;
        try{ await navigator.clipboard.writeText(txt); copyBtn.textContent='Copied'; setTimeout(()=>copyBtn.textContent='Copy summary',1400);}catch(e){ alert('Unable to copy — please select and copy manually.'); }
      });
    })();
  </script>
</body>
</html>"} 
{"path":"conditions.html","content":"<!doctype html>
<html lang="en">
<head>
  <meta charset="utf-8">
  <meta name="viewport" content="width=device-width,initial-scale=1">
  <title>Concerns — {{BUSINESS_NAME}}</title>
  <style>
    :root{--bg:#fffefb;--muted:#67655e;--accent:#7aa78f;--ink:#1f1f1d}
    body{margin:0;font-family:Inter, system-ui, -apple-system, 'Segoe UI', Roboto, Arial;background:var(--bg);color:var(--ink)}
    header{display:flex;align-items:center;justify-content:space-between;padding:14px 22px;border-bottom:1px solid rgba(0,0,0,0.04);background:#fff}
    nav a{margin-left:16px;color:var(--muted);text-decoration:none;font-weight:600}
    main{padding:28px}
    h1{margin:0 0 8px 0}
    .muted{color:var(--muted)}
    .grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(220px,1fr));gap:16px;margin-top:18px}
    .card{background:#fff;padding:16px;border-radius:12px;border:1px solid rgba(0,0,0,0.04)}
    .disclaimer{background:#fff6f1;border-left:4px solid #f0c6b0;padding:12px;border-radius:8px}
    footer{padding:28px;text-align:center}
    .reveal{opacity:0;transform:translateY(12px);transition:opacity .55s ease,transform .55s ease}
    .reveal.is-revealed{opacity:1;transform:none}
    @media(max-width:700){main{padding:18px}}
  </style>
</head>
<body>
  <header>
    <div style="font-weight:800">{{BUSINESS_NAME}}</div>
    <nav>
      <a href="index.html">Hearth</a>
      <a href="services.html">Offerings</a>
      <a href="conditions.html" aria-current="page">Concerns</a>
      <a href="approach.html">Way</a>
      <a href="pricing.html">Plans</a>
      <a href="book.html">Reserve</a>
    </nav>
  </header>

  <main>
    <section class="reveal" data-delay="0">
      <h1>Common concerns we support</h1>
      <p class="muted">Accessible, evidence-aware guidance and practical strategies. Work here is educational and tailored — not curative. We collaborate with your existing care as needed.</p>
    </section>

    <section style="margin-top:18px" class="reveal" data-delay="80">
      <div class="disclaimer">
        <strong>Important:</strong> This information is educational and supportive. We do not promise cures. If you have an urgent medical issue, severe symptoms, or thoughts of harming yourself, seek emergency care or call local emergency services immediately.
      </div>
    </section>

    <section style="margin-top:20px" class="reveal" data-delay="160">
      <div class="grid">
        <div class="card">
          <h3 style="margin:0 0 6px 0">Sleep & Rest</h3>
          <div class="muted">Difficulty falling or staying asleep; unrefreshing sleep.</div>
          <p class="muted" style="margin-top:8px">We offer gentle, behavior-focused experiments to support sleep opportunity and consistency. If insomnia is severe, we coordinate with medical providers.</p>
        </div>

        <div class="card">
          <h3 style="margin:0 0 6px 0">Digestive patterns</h3>
          <div class="muted">Bloating, irregularity, or discomfort that impacts daily life.</div>
          <p class="muted" style="margin-top:8px">We map meals and symptoms to find manageable adjustments. We do not replace gastroenterology diagnostics when needed.</p>
        </div>

        <div class="card">
          <h3 style="margin:0 0 6px 0">Energy & Fatigue</h3>
          <div class="muted">Low energy, fluctuating stamina, or trouble sustaining routines.</div>
          <p class="muted" style="margin-top:8px">We look for small pacing changes, nutrition cues, and sleep hygiene that fit your life. For persistent fatigue, lab work and medical review are recommended.</p>
        </div>

        <div class="card">
          <h3 style="margin:0 0 6px 0">Mood & Stress</h3>
          <div class="muted">Ongoing low mood, anxiety, or high reactivity to daily stressors.</div>
          <p class="muted" style="margin-top:8px">We teach micro-practices and structure daily choices to reduce burden. For clinical depression or panic, we support collaboration with mental health professionals.</p>
        </div>

        <div class="card">
          <h3 style="margin:0 0 6px 0">Hormonal Transitions</h3>
          <div class="muted">Irregular cycles, perimenopause, postpartum changes.</div>
          <p class="muted" style="margin-top:8px">We center timing, symptom tracking, and lifestyle shifts that feel realistic. Medical evaluation is part of decision-making in many transitions.</p>
        </div>

        <div class="card">
          <h3 style="margin:0 0 6px 0">Chronic aches</h3>
          <div class="muted">Low-level pain or tension that limits comfort.</div>
          <p class="muted" style="margin-top:8px">We explore movement, sleep, and small environmental shifts. For severe pain, imaging or specialist referral may be necessary.</p>
        </div>
      </div>
    </section>

    <section style="margin-top:22px" class="reveal" data-delay="240">
      <h2 style="margin-bottom:8px">How we work with concerns</h2>
      <p class="muted">Visits focus on mapping what is already happening, testing one or two doable changes, and watching for measurable effects. Plans emphasize the smallest step that could matter.</p>
    </section>

    <section style="margin-top:22px;padding:18px;background:#fff;border-radius:10px;border:1px solid rgba(0,0,0,0.04)" class="reveal" data-delay="320">
      <h3 style="margin-top:0">Need to talk sooner?</h3>
      <p class="muted">If your symptoms change quickly or you feel unsafe, contact your local emergency services. For non-urgent questions, call our office at <strong>{{PHONE}}</strong> or message <a href="mailto:{{EMAIL}}">{{EMAIL}}</a>.</p>
    </section>

    <footer style="margin-top:28px;text-align:center" class="reveal" data-delay="400">
      <a href="book.html" style="background:var(--accent);color:#fff;padding:12px 16px;border-radius:10px;text-decoration:none;font-weight:700">Book a consult</a>
      <div style="margin-top:10px;color:var(--muted);font-size:13px">Located in {{CITY}}, {{STATE}}</div>
    </footer>
  </main>

  <script>
    // Simple reveal respecting reduced motion
    (function(){
      const prefersReduce = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      const items = document.querySelectorAll('.reveal');
      if(prefersReduce){ items.forEach(i=>i.classList.add('is-revealed')); return; }
      const io = new IntersectionObserver((entries)=>{
        entries.forEach(e=>{
          if(e.isIntersecting){ e.target.classList.add('is-revealed'); io.unobserve(e.target); }
        });
      },{threshold:0.08});
      items.forEach(i=>io.observe(i));
    })();
  </script>
</body>
</html>"} 
