  <script>
    // reveal with reduced motion respect
    (function(){
      const prefersReduce = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
      const items = document.querySelectorAll('.reveal');
      if(prefersReduce){ items.forEach(i=>i.classList.add('is-revealed')); return; }
      const io = new IntersectionObserver((entries)=>{
        entries.forEach(e=>{
          if(e.isIntersecting){
            const delay = parseInt(e.target.getAttribute('data-delay')||0,10);
            setTimeout(()=>e.target.classList.add('is-revealed'), delay);
            io.unobserve(e.target);
          }
        });
      },{threshold:0.1});
      items.forEach(i=>io.observe(i));
    })();

    // Small Session Planner for Approach page
    (function(){
      const draft = document.getElementById('draftA');
      const copyBtn = document.getElementById('copyA');
      const out = document.getElementById('outA');
      function make(){
        const focus = document.getElementById('concernA').value.trim();
        const cons = document.getElementById('constraintA').value.trim();
        const mini = document.getElementById('miniA').value.trim();
        const lines = [];
        lines.push('Micro-plan — '+new Date().toLocaleDateString());
        if(focus) lines.push('Focus: '+focus);
        if(cons) lines.push('Constraint: '+cons);
        if(mini) lines.push('Micro-step: '+mini);
        lines.push('Measure: How will you notice if it helps? (eg. hours of sleep, mood rating, fewer spikes)');
        return lines.join('\n');
      }
      draft.addEventListener('click',function(e){ e.preventDefault(); out.textContent = make(); });
      copyBtn.addEventListener('click',async function(){ const txt = out.textContent; if(!txt) return; try{ await navigator.clipboard.writeText(txt); copyBtn.textContent='Copied'; setTimeout(()=>copyBtn.textContent='Copy',1200);}catch(e){ alert('Copy not available'); } });
    })();
  </script>
